diff --git a/repro/print-types.js b/repro/print-types.js
new file mode 100644
index 000000000..1c2e53932
--- /dev/null
+++ b/repro/print-types.js
@@ -0,0 +1,22 @@
+// Usage: node repro/print-types.js [path-to-typescript.js]
+// Defaults to the locally built compiler (built/local/typescript.js).
+// Prints how the checker displays Test / Test2 from repro/repro.ts, plus the
+// actual type of their `prop1` property as returned by the checker.
+const path = require("path");
+const tsPath = process.argv[2] ? path.resolve(process.argv[2]) : path.join(__dirname, "../built/local/typescript.js");
+const ts = require(tsPath);
+const file = path.join(__dirname, "repro.ts");
+const program = ts.createProgram([file], { strict: true, noEmit: true, target: ts.ScriptTarget.ESNext, types: [] });
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+console.log(`typescript ${ts.version}`);
+for (const stmt of sf.statements) {
+    if (ts.isTypeAliasDeclaration(stmt) && (stmt.name.text === "Test" || stmt.name.text === "Test2")) {
+        const t = checker.getTypeAtLocation(stmt.name);
+        const flags = ts.TypeFormatFlags.NoTruncation | ts.TypeFormatFlags.InTypeAlias;
+        const prop = checker.getPropertyOfType(t, "prop1");
+        const propType = prop && checker.getTypeOfSymbol(prop);
+        console.log(`${stmt.name.text} displays as: ${checker.typeToString(t, undefined, flags)}`);
+        console.log(`${stmt.name.text}["prop1"] actual type: ${propType && checker.typeToString(propType)}`);
+    }
+}
diff --git a/repro/repro.ts b/repro/repro.ts
new file mode 100644
index 000000000..ad1c5fd88
--- /dev/null
+++ b/repro/repro.ts
@@ -0,0 +1,34 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
+
+// Expected: Test is { prop1: "hello"; }.
+// Bug (5.7+): Test is displayed as { prop1: Wrapper<"hello">; }.
+// The deliberate error below makes tsc print the displayed type of Test.
+const probe: number = null! as Test;
+
+// Workaround from the report (assertion on a separate line) for comparison.
+const strWrapper = stringWrapper() as Wrapper<"hello">;
+const value2 = objWrapper({
+    prop1: strWrapper
+});
+type Test2 = Unwrap<typeof value2>
+const probe2: number = null! as Test2; // displays { prop1: "hello"; } (correct)
